import java.io.*;
import java.util.*;

public class Main {
    static final InputStream IN = System.in;
    static final byte[] BUF = new byte[1 << 16];
    static int len, ptr;

    static int readByte() throws IOException {
        if (ptr == len) {
            len = IN.read(BUF, 0, BUF.length);
            ptr = 0;
            if (len <= 0) {
                len = 0;
                return -1;
            }
        }
        return BUF[ptr++];
    }

    static long nextLong() throws IOException {
        int c = readByte();
        while (c == ' ' || c == '\n' || c == '\r' || c == '\t') c = readByte();
        boolean neg = c == '-';
        if (neg) c = readByte();
        long v = 0;
        while (c >= '0' && c <= '9') {
            v = v * 10 + (c - '0');
            c = readByte();
        }
        return neg ? -v : v;
    }

    static int nextInt() throws IOException {
        return (int) nextLong();
    }

    static String next() throws IOException {
        int c = readByte();
        while (c == ' ' || c == '\n' || c == '\r' || c == '\t') c = readByte();
        StringBuilder sb = new StringBuilder();
        while (c > ' ') {
            sb.append((char) c);
            c = readByte();
        }
        return sb.toString();
    }

    public static void main(String[] args) throws IOException {
        int n = nextInt(), m = nextInt();
        int[][] pos = new int[n][m];
        for (int u = 0; u < n; u++)
            for (int k = 0; k < m; k++) pos[u][nextInt()] = k;
        int[] wins = new int[m];
        for (int x = 0; x < m; x++)
            for (int y = 0; y < m; y++) {
                if (x == y) continue;
                int v = 0;
                for (int u = 0; u < n; u++)
                    if (pos[u][x] < pos[u][y]) v++;
                if (2 * v > n || (2 * v == n && x < y)) wins[x]++;
            }
        Integer[] order = new Integer[m];
        for (int i = 0; i < m; i++) order[i] = i;
        Arrays.sort(order, (a, b) -> wins[a] != wins[b] ? wins[b] - wins[a] : a - b);
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < m; i++) {
            if (i > 0) sb.append(' ');
            sb.append(order[i]);
        }
        System.out.print(sb.append('\n'));
    }
}

package main

import (
	"io"
	"os"
	"sort"
	"strconv"
	"strings"
)

var data []byte
var pos int

// token returns the next whitespace-separated token of stdin.
func token() []byte {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	start := pos
	for pos < len(data) && data[pos] > ' ' {
		pos++
	}
	return data[start:pos]
}

func nextInt() int {
	b := token()
	neg := len(b) > 0 && b[0] == '-'
	if neg {
		b = b[1:]
	}
	v := 0
	for _, c := range b {
		v = v*10 + int(c-'0')
	}
	if neg {
		return -v
	}
	return v
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	n, m := nextInt(), nextInt()
	pos := make([][]int, n)
	for u := range pos {
		pos[u] = make([]int, m)
		for k := 0; k < m; k++ {
			pos[u][nextInt()] = k
		}
	}
	wins := make([]int, m)
	for x := 0; x < m; x++ {
		for y := 0; y < m; y++ {
			if x == y {
				continue
			}
			v := 0
			for u := 0; u < n; u++ {
				if pos[u][x] < pos[u][y] {
					v++
				}
			}
			if 2*v > n || (2*v == n && x < y) {
				wins[x]++
			}
		}
	}
	order := make([]int, m)
	for i := range order {
		order[i] = i
	}
	sort.SliceStable(order, func(i, j int) bool { return wins[order[i]] > wins[order[j]] })
	out := make([]string, m)
	for i, s := range order {
		out[i] = strconv.Itoa(s)
	}
	os.Stdout.WriteString(strings.Join(out, " ") + "\n")
}
